hostile_css_source:
.normal { color: green; }
.critical { color: red; font-weight: bold; }
.form-table { border-collapse: separate; }
.form-row { background: transparent; }
.form-label { font-style: normal; }
.form-value { letter-spacing: normal; }
.field-priority { text-decoration: none; }
input[type="text"] { width: 100%; }
span { outline: 0; }
div { outline: 0; }

